package vn.edu.eaut.lab5.dal;
import vn.edu.eaut.lab5.config.DBHelper; import vn.edu.eaut.lab5.model.*; import java.math.BigDecimal; import java.sql.*; import java.time.LocalDate;
public class ThongKeDAL {
 public BigDecimal doanhThu(LocalDate a,LocalDate b)throws SQLException{String q="SELECT COALESCE(SUM(tong_tien),0) FROM hoa_don WHERE ngay_lap BETWEEN ? AND ?";try(Connection c=DBHelper.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setDate(1,Date.valueOf(a));p.setDate(2,Date.valueOf(b));try(ResultSet r=p.executeQuery()){r.next();return r.getBigDecimal(1);}}}
 public HoaDon hoaDonLonNhat(LocalDate a,LocalDate b)throws SQLException{String q="SELECT h.ma_hd,h.ma_kh,h.ngay_lap,h.tong_tien,k.ten_kh,k.sdt FROM hoa_don h JOIN khach_hang k ON k.ma_kh=h.ma_kh WHERE h.ngay_lap BETWEEN ? AND ? ORDER BY h.tong_tien DESC LIMIT 1";try(Connection c=DBHelper.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setDate(1,Date.valueOf(a));p.setDate(2,Date.valueOf(b));try(ResultSet r=p.executeQuery()){if(!r.next())return null;HoaDon h=new HoaDon();h.setMaHd(r.getInt("ma_hd"));h.setMaKh(r.getInt("ma_kh"));h.setNgayLap(r.getDate("ngay_lap").toLocalDate());h.setTongTien(r.getBigDecimal("tong_tien"));h.setTenKh(r.getString("ten_kh"));h.setSdtKh(r.getString("sdt"));return h;}}}
 public Object[] sanPhamBanChay(LocalDate a,LocalDate b)throws SQLException{String q="SELECT sp.ten_sp,SUM(ct.so_luong) sl FROM chi_tiet_hoa_don ct JOIN hoa_don h ON h.ma_hd=ct.ma_hd JOIN san_pham sp ON sp.ma_sp=ct.ma_sp WHERE h.ngay_lap BETWEEN ? AND ? GROUP BY sp.ma_sp,sp.ten_sp ORDER BY sl DESC LIMIT 1";try(Connection c=DBHelper.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setDate(1,Date.valueOf(a));p.setDate(2,Date.valueOf(b));try(ResultSet r=p.executeQuery()){if(r.next())return new Object[]{r.getString(1),r.getInt(2)};return null;}}}
}
